// Lab 19.1, provided: lab 6.4's `linear` kernel (the project's M2), bound with byte
// offsets. You do not edit this file.
//
// It does exactly what lab 6.4's encodeLinear does (buffers X, W, Y at indices 0, 1, 2,
// the LinearDims {batch, in, out} struct at index 3, (ceil(out / T), ceil(batch / T))
// threadgroups of T x T threads) except that each buffer is bound at a byte offset into
// it. Your encodeConvGemm uses the offset on Y, so that sample n's result lands at
// Y + n * M * P: the Metal counterpart of passing the CUDA pointer Y + n * M * P.
//
// Offsets are in bytes. For a buffer read as `device float*`, Apple asks that the
// offset be aligned to the data type's size (notes/today/ch06-facts.md C3): any whole
// number of floats, times 4, is.
//   Y = X * W^T, X: batch x in at X + xOff, W: out x in at W + wOff, Y: batch x out at Y + yOff.
#import <Metal/Metal.h>
#include <cstdint>

struct LinearAtDims { int32_t batch, in, out; };   // lab 6.4's LinearDims, field for field

void encodeLinearAt(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> pipeline,
                    id<MTLBuffer> X, NSUInteger xOff, id<MTLBuffer> W, NSUInteger wOff,
                    id<MTLBuffer> Y, NSUInteger yOff,
                    int32_t batch, int32_t in, int32_t out, int32_t tileWidth) {
    LinearAtDims d = {batch, in, out};
    [enc setComputePipelineState:pipeline];
    [enc setBuffer:X offset:xOff atIndex:0];
    [enc setBuffer:W offset:wOff atIndex:1];
    [enc setBuffer:Y offset:yOff atIndex:2];
    [enc setBytes:&d length:sizeof(d) atIndex:3];
    const NSUInteger t = (NSUInteger)tileWidth;
    MTLSize groups = MTLSizeMake(((NSUInteger)out + t - 1) / t,     // x covers the outputs (columns of Y)
                                 ((NSUInteger)batch + t - 1) / t,   // y covers the batch (rows of Y)
                                 1);
    [enc dispatchThreadgroups:groups threadsPerThreadgroup:MTLSizeMake(t, t, 1)];
}
